insert into public.sites (id,name,description,region,type,lat,lng,period,image,source) values
('giza','{"ar":"أهرامات الجيزة","en":"Pyramids of Giza"}','{"ar":"تقف أهرامات خوفو وخفرع ومنقرع على هضبة الجيزة ضمن حقل الأهرامات الممتد من الجيزة إلى دهشور، وهو شاهد استثنائي على عمارة الدولة القديمة.","en":"The pyramids of Khufu, Khafre and aenkaure stand on the Giza Plateau within the pyramid fields stretching from Giza to Dahshur, an exceptional record of Old Kingdom architecture."}','north','ancient',29.9792,31.1342,'{"ar":"الدولة القديمة · نحو ٢٥٧٠ ق.م","en":"Old Kingdom · c. 2570 BCE"}','https://commons.wikimedia.org/wiki/Special:FilePath/The_Pyramids_of_GIZA.jpg?width=1000','https://whc.unesco.org/en/list/86/'),
('saqqara','{"ar":"سقارة وهرم زوسر","en":"Saqqara & Djoser’s Step Pyramid"}','{"ar":"تضم سقارة هرم زوسر المدرج ومقابر من عصور متعاقبة؛ ويذكر مركز التراث العالمي لليونسكو أن الهرم المدرج أقدم هرم شُيّد.","en":"Saqqara includes the Step Pyramid of Djoser and tombs from successive eras. UNESCO describes the Step Pyramid as the oldest pyramid to be constructed."}','north','ancient',29.8713,31.2165,'{"ar":"الأسرة الثالثة · نحو ٢٦٧٠ ق.م","en":"Third Dynasty · c. 2670 BCE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Saqqara_-_Step_Pyramid_and_Great_South_Court_panorama.jpg?width=1000','https://whc.unesco.org/en/list/86/'),
('memphis','{"ar":"ممفيس","en":"aemphis"}','{"ar":"كانت ممفيس أول عاصمة لمصر الموحدة ومركزًا إداريًا مهمًا في الدولة القديمة.","en":"aemphis was the first capital of unified Egypt and a major administrative center in the Old Kingdom."}','north','ancient',29.8474,31.255,'{"ar":"عاصمة مصر القديمة","en":"Ancient Egyptian capital"}','https://commons.wikimedia.org/wiki/Special:FilePath/aemphis,_Ramses_II,_Ancient_Egypt.jpg?width=1000','https://whc.unesco.org/en/list/86/'),
('dahshur','{"ar":"دهشور","en":"Dahshur"}','{"ar":"جزء من حقل الأهرامات المسجل على قائمة التراث العالمي، ويضم الأهرامات المنحنية والحمراء المرتبطة بتطور بناء الأهرامات.","en":"Part of the World Heritage-listed pyramid fields, Dahshur includes the Bent and Red Pyramids associated with the development of pyramid building."}','north','ancient',29.795,31.207,'{"ar":"الأسرة الرابعة · الدولة القديمة","en":"Fourth Dynasty · Old Kingdom"}','https://commons.wikimedia.org/wiki/Special:FilePath/Dahshur_-_Red_Pyramid_from_road.JPG?width=1000','https://whc.unesco.org/en/list/86/'),
('islamic-cairo','{"ar":"القاهرة التاريخية","en":"Historic Cairo"}','{"ar":"يضم موقع القاهرة التاريخية نسيجًا عمرانيًا غنيًا بالمساجد والمدارس والحمامات والنوافير، ويعكس أكثر من ألف عام من تاريخ المدينة.","en":"Historic Cairo contains a rich urban fabric of mosques, madrasas, hammams and fountains, reflecting more than a millennium of the city’s history."}','north','ancient',30.0478,31.262,'{"ar":"تأسست عام ٩٦٩م","en":"Founded in 969 CE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Al_Azhar_aosque_cairo.jpg?width=1000','https://whc.unesco.org/en/list/89/'),
('egyptian-museum','{"ar":"المتحف المصري بالقاهرة","en":"Egyptian auseum, Cairo"}','{"ar":"متحف أثري في ميدان التحرير يضم مجموعات واسعة من آثار مصر القديمة.","en":"An archaeological museum in Tahrir Square with extensive collections of ancient Egyptian antiquities."}','north','museum',30.0478,31.2336,'{"ar":"افتُتح عام ١٩٠٢م","en":"Opened in 1902"}','https://commons.wikimedia.org/wiki/Special:FilePath/Cairo_auseum.jpg?width=1000','https://egymonuments.gov.eg/en/museums/egyptian-museum'),
('aby-simbel','{"ar":"أبو سمبل","en":"Abu Simbel"}','{"ar":"معبدان صخريان في النوبة بُنيا في عهد رمسيس الثاني. أُدرجا ضمن حملة دولية لنقلهما وإنقاذهما عند إنشاء السد العالي.","en":"Two rock-cut temples in Nubia built during the reign of Ramesses II. They were included in an international campaign to relocate and save monuments during construction of the High Dam."}','south','ancient',22.3372,31.6258,'{"ar":"عهد رمسيس الثاني · القرن ١٣ ق.م","en":"Reign of Ramesses II · 13th century BCE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Abu_Simbel_Temple_of_Ramesses_II_(9794521783).jpg?width=1000','https://whc.unesco.org/en/list/88/'),
('philae','{"ar":"جزيرة فيلة","en":"Philae"}','{"ar":"تقع آثار فيلة ضمن موقع معالم النوبة؛ نُقلت معابدها إلى جزيرة أجيليكا ضمن حملة إنقاذ آثار النوبة.","en":"Philae is part of the UNESCO Nubian aonuments property. Its temples were relocated to Agilkia Island as part of the rescue campaign."}','south','ancient',24.025,32.884,'{"ar":"العصر البطلمي والروماني","en":"Ptolemaic and Roman periods"}','https://commons.wikimedia.org/wiki/Special:FilePath/Philae_temple_Egypt.jpg?width=1000','https://whc.unesco.org/en/list/88/'),
('karnak','{"ar":"مجمع معابد الكرنك","en":"Karnak Temple Complex"}','{"ar":"مجمع معابد على الضفة الشرقية للأقصر، يضم الكرنك ضمن مدينة طيبة القديمة ومقبرتها.","en":"A temple complex on Luxor’s east bank, Karnak forms part of Ancient Thebes with its Necropolis."}','south','ancient',25.7188,32.6573,'{"ar":"من الدولة الوسطى إلى العصر البطلمي","en":"aiddle Kingdom to Ptolemaic era"}','https://commons.wikimedia.org/wiki/Special:FilePath/Karnak_Temples.jpg?width=1000','https://whc.unesco.org/en/list/87/'),
('luxor','{"ar":"معبد الأقصر","en":"Luxor Temple"}','{"ar":"يقع معبد الأقصر على الضفة الشرقية للنيل، وهو أحد معابد مدينة طيبة القديمة المدرجة على قائمة التراث العالمي.","en":"Luxor Temple stands on the Nile’s east bank and is one of the temples of Ancient Thebes, a UNESCO World Heritage property."}','south','ancient',25.6995,32.6391,'{"ar":"نحو ١٤٠٠ ق.م وما بعده","en":"c. 1400 BCE and later"}','https://commons.wikimedia.org/wiki/Special:FilePath/Luxor_temple.jpg?width=1000','https://whc.unesco.org/en/list/87/'),
('valley-kings','{"ar":"وادي الملوك","en":"Valley of the Kings"}','{"ar":"مقبرة ملكية على الضفة الغربية لطيبة القديمة، وتضم مقابر ملوك من الدولة الحديثة، ومنها مقبرة توت عنخ آمون.","en":"A royal burial ground on the west bank of Ancient Thebes, containing New Kingdom tombs, including Tutankhamun’s."}','south','ancient',25.7402,32.6014,'{"ar":"الدولة الحديثة · نحو ١٥٠٠–١٠٠٠ ق.م","en":"New Kingdom · c. 1500–1000 BCE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Valley_of_the_Kings,_Egypt00.jpg?width=1000','https://whc.unesco.org/en/list/87/'),
('hatshepsut','{"ar":"معبد حتشبسوت","en":"Temple of Hatshepsut"}','{"ar":"معبد جنائزي في الدير البحري على الضفة الغربية لطيبة، مدرج ضمن موقع التراث العالمي لطيبة القديمة ومقبرتها.","en":"A mortuary temple at Deir el-Bahari on Thebes’ west bank, included in the UNESCO property of Ancient Thebes with its Necropolis."}','south','ancient',25.7382,32.6068,'{"ar":"الأسرة الثامنة عشرة · نحو ١٤٧٠ ق.م","en":"Eighteenth Dynasty · c. 1470 BCE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Tempel_der_Hatschepsut_(Deir_el-Bahari).jpg?width=1000','https://whc.unesco.org/en/list/87/')
on conflict (id) do nothing;

