insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('elephantine','{"ar":"جزيرة إلفنتين","en":"Elephantine Island"}','{"ar":"جزيرة نيلية أثرية تضم بقايا مدينة قديمة ضمن آثار النوبة.","en":"An archaeological Nile island with remains of an ancient town in the Nubian aonuments property."}','south','ancient',24.0889,32.887,'{"ar":"عصور متعددة","en":"Several periods"}','https://commons.wikimedia.org/wiki/Special:FilePath/Aswan_Elephantine_Island_R02.jpg?width=1000','https://whc.unesco.org/en/list/88/','{"ar":"أسوان","en":"Aswan"}','aarc Ryckaert · CC BY 3.0','https://commons.wikimedia.org/wiki/File:Aswan_Elephantine_Island_R02.jpg','https://creativecommons.org/licenses/by/3.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('saint-catherine','{"ar":"منطقة سانت كاترين","en":"Saint Catherine Area"}','{"ar":"منطقة جبلية ذات أهمية دينية وثقافية تضم دير سانت كاترين.","en":"A mountainous area of religious and cultural significance, including Saint Catherine’s aonastery."}','north','ancient',28.5559,33.976,'{"ar":"موقع تراث عالمي · ٢٠٠٢","en":"World Heritage · 2002"}','https://commons.wikimedia.org/wiki/Special:FilePath/Saint_Catherine''s_aonastery,_photo_by_Hatem_aoushir_10.jpg?width=1000','https://whc.unesco.org/en/list/954/','{"ar":"جنوب سيناء","en":"South Sinai"}','Hatem aoushir · CC BY-SA 4.0','https://commons.wikimedia.org/wiki/File:Saint_Catherine''s_aonastery,_photo_by_Hatem_aoushir_10.jpg','https://creativecommons.org/licenses/by-sa/4.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('wadi-hitan','{"ar":"وادي الحيتان","en":"Wadi Al-Hitan (Whale Valley)"}','{"ar":"محمية صحراوية تحفظ حفريات توثق تطور الحيتان.","en":"A protected desert area with fossils documenting whale evolution."}','central','ancient',29.321,30.19,'{"ar":"تراث طبيعي عالمي · ٢٠٠٥","en":"Natural World Heritage · 2005"}','https://commons.wikimedia.org/wiki/Special:FilePath/Wadi_Al-Hitan_national_park.jpg?width=1000','https://whc.unesco.org/en/list/1186','{"ar":"الفيوم · الصحراء الغربية","en":"Fayoum · Western Desert"}','aohamed aostafa Abdelraheem · CC BY-SA 4.0','https://commons.wikimedia.org/wiki/File:Wadi_Al-Hitan_national_park.jpg','https://creativecommons.org/licenses/by-sa/4.0/') on conflict (id) do nothing;
