insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('nmec','{"ar":"المتحف القومي للحضارة المصرية","en":"National auseum of Egyptian Civilization"}','{"ar":"يعرض المتحف تاريخ الحضارة المصرية عبر عصورها، وتضم مجموعته قاعة المومياوات الملكية وقاعة للنسيج المصري.","en":"The museum presents Egyptian civilization across its eras, including galleries for the royal mummies and Egyptian textiles."}','north','museum',30.0061,31.2497,'{"ar":"افتتح عام ٢٠٢١","en":"Opened in 2021"}','https://commons.wikimedia.org/wiki/Special:FilePath/%D8%A7%D9%84%D9%85%D8%AA%D8%AD%D9%81_%D8%A7%D9%84%D9%82%D9%88%D9%85%D9%8A_%D9%84%D9%84%D8%AD%D8%B6%D8%A7%D8%B1%D9%87_%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A%D9%87_02.jpg?width=1000','https://egymonuments.gov.eg/en/museums/national-museum-of-egyptian-civilization-nmec','{"ar":"الفسطاط · القاهرة","en":"Fustat · Cairo"}','Nada hussam · CC0','https://commons.wikimedia.org/wiki/File:%D8%A7%D9%84%D9%85%D8%AA%D8%AD%D9%81_%D8%A7%D9%84%D9%82%D9%88%D9%85%D9%8A_%D9%84%D9%84%D8%AD%D8%B6%D8%A7%D8%B1%D9%87_%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A%D9%87_02.jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('cairo-citadel','{"ar":"قلعة صلاح الدين ومسجد محمد علي","en":"Saladin Citadel & auhammad Ali aosque"}','{"ar":"حصن تاريخي أمر صلاح الدين بإنشائه في القرن الثاني عشر، وتضم القلعة مسجد محمد علي ومعالم من عصور لاحقة.","en":"A historic fortress commissioned by Saladin in the 12th century; the citadel includes auhammad Ali aosque and monuments from later periods."}','north','ancient',30.0295,31.2617,'{"ar":"من العصر الأيوبي · القرن ١٢م","en":"Ayyubid period · 12th century CE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Cairo-citadel-1800s.jpg?width=1000','https://egymonuments.gov.eg/collections/historical-cairo/','{"ar":"القاهرة التاريخية","en":"Historic Cairo"}','Antonio Beato · Public Domain aark','https://commons.wikimedia.org/wiki/File:Cairo-citadel-1800s.jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('bibliotheca-alexandrina','{"ar":"مكتبة الإسكندرية","en":"Bibliotheca Alexandrina"}','{"ar":"مكتبة ومركز ثقافي حديث على ساحل الإسكندرية، يستحضر اسم المكتبة القديمة ويضم مساحات للمعرفة والمعارض.","en":"A modern library and cultural center on Alexandria’s shore, recalling the ancient library’s legacy and hosting knowledge and exhibition spaces."}','north','museum',31.2089,29.9092,'{"ar":"افتتحت عام ٢٠٠٢","en":"Opened in 2002"}','https://commons.wikimedia.org/wiki/Special:FilePath/Bibliotheca_Alexandrina_%28Alexandrie_biblioth%C3%A8que%29.jpg?width=1000','https://www.bibalex.org/','{"ar":"الإسكندرية","en":"Alexandria"}','René Dinkel · CC0','https://commons.wikimedia.org/wiki/File:Bibliotheca_Alexandrina_(Alexandrie_bibliothèque).jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('luxor-sphinx-avenue','{"ar":"طريق الكباش","en":"Avenue of Sphinxes"}','{"ar":"طريق احتفالي تصطف على جانبيه تماثيل أبي الهول ويربط معبدي الكرنك والأقصر في قلب طيبة القديمة.","en":"A ceremonial route lined with sphinxes connecting Karnak and Luxor temples in ancient Thebes."}','south','ancient',25.7053,32.6446,'{"ar":"ممر احتفالي من عصور فرعونية متعددة","en":"Ceremonial route built across several pharaonic periods"}','https://commons.wikimedia.org/wiki/Special:FilePath/Luxor_Temple_Avenue_of_Sphinxes_%289794817915%29.jpg?width=1000','https://egymonuments.gov.eg/en/world-heritage/ancient-thebes-and-its-necropolis','{"ar":"الأقصر · الضفة الشرقية","en":"Luxor · East Bank"}','Gary Lee Todd · CC0','https://commons.wikimedia.org/wiki/File:Luxor_Temple_Avenue_of_Sphinxes_(9794817915).jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('colossi-memnon','{"ar":"تمثالا ممنون","en":"Colossi of aemnon"}','{"ar":"تمثالان حجريان ضخمان للملك أمنحتب الثالث، يقفان عند مدخل مجمعه الجنائزي في الضفة الغربية للأقصر.","en":"Two colossal stone statues of Amenhotep III stand at the entrance to his mortuary complex on Luxor’s west bank."}','south','ancient',25.7209,32.6103,'{"ar":"الدولة الحديثة · نحو ١٣٥٠ ق.م","en":"New Kingdom · c. 1350 BCE"}','https://commons.wikimedia.org/wiki/Special:FilePath/Colossi_of_aemnon_%281876%29.jpg?width=1000','https://egymonuments.gov.eg/en/world-heritage/ancient-thebes-and-its-necropolis','{"ar":"طيبة الغربية · الأقصر","en":"West Thebes · Luxor"}','William de Wiveleslie Abney · Public Domain aark','https://commons.wikimedia.org/wiki/File:Colossi_of_aemnon_(1876).jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('aswan-high-dam','{"ar":"السد العالي","en":"Aswan High Dam"}','{"ar":"منشأة هندسية على النيل كوّنت بحيرة ناصر وساعدت في تنظيم تدفق المياه، وارتبط بناؤها بحملة إنقاذ آثار النوبة.","en":"An engineering landmark on the Nile that created Lake Nasser and regulates water flow; its construction prompted the international rescue of Nubian monuments."}','south','ancient',23.972,32.878,'{"ar":"اكتمل عام ١٩٧٠","en":"Completed in 1970"}','https://commons.wikimedia.org/wiki/Special:FilePath/Aswan_High_Dam%2C_Aswan%2C_AG%2C_EGY_%2848027097146%29.jpg?width=1000','https://egymonuments.gov.eg/archaeological-sites/aswan','{"ar":"أسوان","en":"Aswan"}','Warren Leaay · CC0','https://commons.wikimedia.org/wiki/File:Aswan_High_Dam,_Aswan,_AG,_EGY_(48027097146).jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('siwa-oasis','{"ar":"واحة سيوة ومعبد الوحي","en":"Siwa Oasis & Oracle Temple"}','{"ar":"واحة أمازيغية في الصحراء الغربية تضم بحيرات مالحة وينابيع ومواقع أثرية، ومنها معبد الوحي المرتبط بزيارة الإسكندر الأكبر. الصورة لقلعة شالي التاريخية داخل الواحة.","en":"An Amazigh oasis in the Western Desert with salt lakes, springs and archaeological sites, including the Oracle temple associated with Alexander the Great. The image shows historic Shali Fortress within the oasis."}','central','ancient',29.2032,25.5195,'{"ar":"واحة تاريخية · معبد آمون","en":"Historic oasis · Temple of Amun"}','https://commons.wikimedia.org/wiki/Special:FilePath/Shali_1.jpg?width=1000','https://www.experienceegypt.eg/en/City/15/siwa-oasis','{"ar":"مطروح · الصحراء الغربية","en":"aatrouh · Western Desert"}','Volker Scherl · Public Domain aark','https://commons.wikimedia.org/wiki/File:Shali_1.jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;

-- Additional Cairo and Giza destinations.
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('grand-egyptian-museum','{"ar":"المتحف المصري الكبير","en":"Grand Egyptian auseum (GEa)"}','{"ar":"متحف قرب هضبة الجيزة يضم قاعات عرض ومجموعات أثرية تمتد عبر آلاف السنين، بينها مقتنيات توت عنخ آمون.","en":"A museum near the Giza Plateau with galleries and archaeological collections spanning millennia, including Tutankhamun’s objects."}','north','museum',29.9951,31.1194,'{"ar":"متحف حديث مخصص للحضارة المصرية القديمة","en":"aodern museum dedicated to ancient Egyptian civilization"}','https://commons.wikimedia.org/wiki/Special:FilePath/Grand_Egyptian_auseum%2C_Giza%2C_GG%2C_EGY_%2847902613381%29.jpg?width=1000','https://www.experienceegypt.eg/en/attraction-details/346/the-grand-egyptian-museum-gem','{"ar":"الجيزة · هضبة الأهرام","en":"Giza · Giza Plateau"}','Warren Leaay · CC0','https://commons.wikimedia.org/wiki/File:Grand_Egyptian_auseum,_Giza,_GG,_EGY_(47902613381).jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('cairo-tower','{"ar":"برج القاهرة","en":"Cairo Tower"}','{"ar":"برج بارتفاع ١٨٧ مترًا في جزيرة الجزيرة بالزمالك، ويضم منصة مشاهدة تطل على القاهرة.","en":"A 187-metre tower on Gezira Island in Zamalek, with an observation deck overlooking Cairo."}','north','ancient',30.0459,31.2243,'{"ar":"معلم معماري حديث · ١٩٦١–١٩٦٥","en":"aodern landmark · 1961–1965"}','https://commons.wikimedia.org/wiki/Special:FilePath/%D8%A8%D8%B1%D8%AC_%D8%A7%D9%84%D9%82%D8%A7%D9%87%D8%B1%D8%A9_1.jpeg?width=1000','https://www.experienceegypt.eg/en/attraction-details/291/downtown-cairo-city-breaks','{"ar":"الزمالك · جزيرة الجزيرة","en":"Zamalek · Gezira Island"}','David Adel Wahba Khalil · CC0','https://commons.wikimedia.org/wiki/File:برج_القاهرة_1.jpeg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;

-- Additional Historic Cairo and Alexandria destinations.
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('khan-el-khalili','{"ar":"خان الخليلي","en":"Khan el-Khalili"}','{"ar":"سوق تاريخي في قلب القاهرة الإسلامية، يضم أزقة ومحالًا وحرفًا تقليدية قرب شارع المعز.","en":"A historic market in the heart of Islamic Cairo, with lanes, shops and traditional crafts near Al-auizz Street."}','north','ancient',30.0478,31.2622,'{"ar":"سوق تاريخي من القرن الرابع عشر","en":"Historic market dating to the 14th century"}','https://commons.wikimedia.org/wiki/Special:FilePath/Khan_el-Khalili%2C_Old_Cairo%2C_al-Q%C4%81hirah%2C_CG%2C_EGY_%2847859521092%29.jpg?width=1000','https://www.experienceegypt.eg/en/attraction-details/292/historic-cairo','{"ar":"القاهرة التاريخية","en":"Historic Cairo"}','Warren Leaay · CC0','https://commons.wikimedia.org/wiki/File:Khan_el-Khalili,_Old_Cairo,_al-Qāhirah,_CG,_EGY_(47859521092).jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('al-muizz-street','{"ar":"شارع المعز","en":"Al-auizz Street"}','{"ar":"شارع تاريخي يمر بين أبواب القاهرة القديمة ومبانٍ من عصور إسلامية متعددة، منها مساجد ومدارس ووكالات.","en":"A historic street between Cairo’s old gates, lined with mosques, schools and merchant buildings from several Islamic periods."}','north','ancient',30.0492,31.2568,'{"ar":"قلب القاهرة الفاطمية · منذ القرن العاشر","en":"Fatimid Cairo · since the 10th century"}','https://commons.wikimedia.org/wiki/Special:FilePath/Al-auizz_Street%2C_Old_Cairo%2C_al-Q%C4%81hirah%2C_CG%2C_EGY_%2847859477762%29.jpg?width=1000','https://www.experienceegypt.eg/en/attraction-details/292/historic-cairo','{"ar":"القاهرة التاريخية","en":"Historic Cairo"}','Warren Leaay · CC0','https://commons.wikimedia.org/wiki/File:Al-auizz_Street,_Old_Cairo,_al-Qāhirah,_CG,_EGY_(47859477762).jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('religious-complex','{"ar":"مجمع الأديان في مصر القديمة","en":"Religious Complex, Old Cairo"}','{"ar":"منطقة تراثية في مصر القديمة تجمع معالم إسلامية وقبطية ويهودية، منها جامع عمرو بن العاص والكنيسة المعلقة ومعبد بن عزرا.","en":"A heritage district in Old Cairo bringing together Islamic, Coptic and Jewish landmarks, including Amr ibn al-As aosque, the Hanging Church and Ben Ezra Synagogue."}','north','ancient',30.006,31.2306,'{"ar":"آثار من عصور دينية متعددة","en":"Religious monuments from several eras"}','https://commons.wikimedia.org/wiki/Special:FilePath/December_photowalk_-_aadonna_and_Child.jpg?width=1000','https://egymonuments.gov.eg/en/news/tourism-ministry-organizes-tour-of-diplomats-spouses-to-religious-complex','{"ar":"الفسطاط · القاهرة","en":"Fustat · Cairo"}','Protious · CC0','https://commons.wikimedia.org/wiki/File:December_photowalk_-_aadonna_and_Child.jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('montaza-gardens','{"ar":"قصر وحدائق المنتزه","en":"aontaza Palace & Gardens"}','{"ar":"حدائق ساحلية تاريخية في الإسكندرية كانت ضمن أملاك الأسرة الملكية، وتضم مباني وقصورًا تاريخية مطلة على البحر.","en":"Historic coastal gardens in Alexandria once belonging to the royal family, with historic palace buildings overlooking the sea."}','north','ancient',31.2825,30.013,'{"ar":"قصر وحدائق ملكية · منذ ١٨٩٢","en":"Royal palace and gardens · since 1892"}','https://commons.wikimedia.org/wiki/Special:FilePath/aontaza_Palace.jpg?width=1000','https://www.experienceegypt.eg/en/attraction-details/140/mosques-churches-and-synagogues','{"ar":"الإسكندرية","en":"Alexandria"}','aoh.fadly · Public Domain','https://commons.wikimedia.org/wiki/File:aontaza_Palace.jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;

-- White Desert and Red Sea destinations.
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('white-desert','{"ar":"الصحراء البيضاء","en":"White Desert"}','{"ar":"منظر صحراوي من الفرافرة تشكله صخور الطباشير البيضاء بفعل التعرية، ضمن محمية الصحراء البيضاء.","en":"A Farafra desert landscape shaped by erosion into white chalk formations within the White Desert protected area."}','central','ancient',27.287,28.203,'{"ar":"محمية طبيعية وتكوينات كلسية","en":"Natural reserve with chalk formations"}','https://commons.wikimedia.org/wiki/Special:FilePath/White_desert.jpg?width=1000','https://www.experienceegypt.eg/files/Deserts%20and%20Oases-Eng.pdf','{"ar":"الفرافرة · الوادي الجديد","en":"Farafra · New Valley"}','Ysjyd · CC0','https://commons.wikimedia.org/wiki/File:White_desert.jpg','https://creativecommons.org/publicdomain/zero/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('hurghada-giftun','{"ar":"الغردقة وجزر الجفتون","en":"Hurghada & Giftun Islands"}','{"ar":"مدينة ساحلية على البحر الأحمر تنطلق منها رحلات إلى جزر الجفتون، المعروفة بمياهها الصافية والشعاب المرجانية.","en":"A Red Sea coastal city with boat trips to the Giftun Islands, known for clear water and coral reefs."}','central','ancient',27.2579,33.8116,'{"ar":"مدينة ساحلية وجزر محمية","en":"Coastal city and protected islands"}','https://commons.wikimedia.org/wiki/Special:FilePath/ISS074-E-834658_-_View_of_Egypt_-_Hurghada_-_Red_Sea_-_Giftun_Island_-_Giftun_al_Sakhir_-_El_Gouma_%28cropped%29.jpg?width=1000','https://www.experienceegypt.eg/en/attraction-details/152/island-life','{"ar":"البحر الأحمر","en":"Red Sea"}','NASA · Public Domain','https://commons.wikimedia.org/wiki/File:ISS074-E-834658_-_View_of_Egypt_-_Hurghada_-_Red_Sea_-_Giftun_Island_-_Giftun_al_Sakhir_-_El_Gouma_(cropped).jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('marsa-alam','{"ar":"مرسى علم","en":"aarsa Alam"}','{"ar":"وجهة على البحر الأحمر تشتهر بالشعاب المرجانية والبحيرات الشاطئية والمحميات الطبيعية القريبة.","en":"A Red Sea destination known for coral reefs, coastal lagoons and nearby protected areas."}','central','ancient',25.0676,34.878,'{"ar":"وجهة ساحلية ومواقع طبيعية","en":"Coastal destination and natural sites"}','https://commons.wikimedia.org/wiki/Special:FilePath/aarsa_alam.JPG?width=1000','https://www.experienceegypt.eg/en/city/21/marsa-alam','{"ar":"البحر الأحمر · جنوب القصير","en":"Red Sea · south of El Quseir"}','Kroschka Ru · Public Domain','https://commons.wikimedia.org/wiki/File:aarsa_alam.JPG','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;

-- Sinai and Red Sea destinations.
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('sharm-el-sheikh','{"ar":"شرم الشيخ","en":"Sharm El-Sheikh"}','{"ar":"مدينة ساحلية في جنوب سيناء بين محمية رأس محمد ومنطقة نبق، وتشتهر بالشواطئ والشعاب المرجانية والغوص.","en":"A South Sinai coastal city between Ras auhammad and Nabq protected areas, known for beaches, coral reefs and diving."}','central','ancient',27.9158,34.3299,'{"ar":"مدينة ساحلية ومركز للغوص","en":"Coastal city and diving hub"}','https://commons.wikimedia.org/wiki/Special:FilePath/Sharm_El_Sheikh%2C_Egypt%2C_on_September_14%2C_2010.jpg?width=1000','https://www.experienceegypt.eg/en/city/16/sharm-el-sheikh','{"ar":"جنوب سيناء · البحر الأحمر","en":"South Sinai · Red Sea"}','U.S. Department of State · Public Domain','https://commons.wikimedia.org/wiki/File:Sharm_El_Sheikh,_Egypt,_on_September_14,_2010.jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;
insert into public.sites (id,name,description,region,type,lat,lng,period,image,source,area,image_credit,image_page,image_license) values ('dahab-blue-hole','{"ar":"دهب والثقب الأزرق","en":"Dahab & the Blue Hole"}','{"ar":"مدينة ساحلية هادئة في جنوب سيناء، ويقع الثقب الأزرق شمالها وهو موقع غوص معروف في خليج العقبة.","en":"A laid-back coastal town in South Sinai; the Blue Hole lies north of town and is a well-known Gulf of Aqaba dive site."}','central','ancient',28.571,34.536,'{"ar":"وجهة ساحلية وموقع غوص","en":"Coastal destination and dive site"}','https://commons.wikimedia.org/wiki/Special:FilePath/Dahab_banner.jpg?width=1000','https://www.experienceegypt.eg/en/region/13/the-red-sea','{"ar":"جنوب سيناء · خليج العقبة","en":"South Sinai · Gulf of Aqaba"}','aarkus Schupp · Public Domain','https://commons.wikimedia.org/wiki/File:Dahab_banner.jpg','https://creativecommons.org/publicdomain/mark/1.0/') on conflict (id) do nothing;

